import { Global, Module } from '@nestjs/common';

import { ReportsCacheService } from './reports-cache.service';

/**
 * Кэш отчётов как общий сервис (задача 5.7).
 *
 * ЗАЧЕМ ГЛОБАЛЬНЫЙ МОДУЛЬ. Кэш должен быть ОДИН на процесс. Nest создаёт
 * отдельный экземпляр провайдера в каждом модуле, который его объявляет: если бы
 * `ReportsCacheService` объявлялся и в модуле отчётов, и в модуле заказов, то
 * заказы сбрасывали бы СВОЙ экземпляр кэша, а отчёты читали бы свой — то есть
 * сброс не работал бы вовсе, и это не проявилось бы как ошибка. Отчёт просто
 * показывал бы старые данные до истечения TTL, и причину искали бы в отчёте.
 *
 * Поэтому сервис живёт здесь и помечен `@Global()`: все модули получают один и
 * тот же экземпляр, и сброс из любого места доходит до отчётов.
 */
@Global()
@Module({
  providers: [ReportsCacheService],
  exports: [ReportsCacheService],
})
export class ReportsCacheModule {}
